unsigned long address = 0x1A2B3C4D5E6F7080UL;

// Subfield definition: Extract bits 16 through 23 (8 bits wide)
const int FIELD_SHIFT = 16;
const int FIELD_WIDTH = 8;

// 1. Generate a mask (8 ones)
const unsigned long MASK = (1UL << FIELD_WIDTH) - 1;

// 2. Shift the field to the LSB position
// 3. Apply the mask to isolate the field
unsigned int extracted_value = (address >> FIELD_SHIFT) & MASK;

// Example: Extracting the lowest N bits (Offset field)
const int OFFSET_BITS = 12;
unsigned int offset = address & ((1UL << OFFSET_BITS) - 1);
